<template>
  <div class="page-wrap">
    <div class="page-head animate-slide-in-up"><div><span class="eyebrow">{{ eyebrow }}</span><h1>今天，也从一小步开始</h1><p>{{ hello }}，{{ nickname }}。把计划变成一次轻松的行动。</p></div><BaseButton @click="router.push('/plan')">查看本周计划</BaseButton></div>
    <RouterLink v-if="!store.hasProfile" to="/onboarding" class="setup animate-slide-in-up">
      <span class="setup-ic"><Sparkles :size="18" /></span>
      <span class="setup-txt"><strong>还没完成建档</strong><small>花一分钟填几项，概览的称呼与"为什么适合你"才会按你的情况来。</small></span>
      <em>去建档 <ArrowRight :size="14" /></em>
    </RouterLink>
    <section class="hero" v-if="store.isPublicMode"><div><span class="hero-kicker">今日训练 · 20 MIN</span><h2>无器材基础体能</h2><p>宿舍 · 无器材 · 无跳跃</p><div class="hero-actions"><BaseButton :icon="Play" @click="start('坐站训练')">开始跟练</BaseButton><BaseButton variant="secondary" :icon="SlidersHorizontal" @click="router.push('/plan')">调整条件</BaseButton></div></div><div class="hero-orb"><Activity :size="38"/><strong>{{ weekValue }}</strong><span>本周完成</span></div></section>
    <section class="hero" v-else><div><span class="hero-kicker">基础准备期 · WEEK 2 / 4</span><h2>跑步专项训练台</h2><p>保持节奏，完成今天的轻松跑。</p><div class="hero-actions"><BaseButton :icon="PlayCircle" @click="start('站姿弯举')">记录实际训练</BaseButton><BaseButton variant="secondary" :icon="GitCompare" @click="router.push('/plan')">查看调整建议</BaseButton></div></div><div class="hero-orb"><TrendingUp :size="38"/><strong>{{ loadValue }}</strong><span>本周负荷</span></div></section>
    <div class="metrics"><MetricCard class="animate-slide-in-up" label="本周训练完成" :value="weekValue" hint="有记录 / 计划场次" :icon="CheckCircle2" :tone="week.plannedSessions > 0 && week.completedSessions === week.plannedSessions ? 'success' : 'default'"/><MetricCard class="animate-slide-in-up" label="今日可用时间" value="20 分钟" hint="适合轻量训练" :icon="Clock3"/><MetricCard class="animate-slide-in-up" :label="mealLabel" :value="mealValue" :hint="mealHint" :icon="Utensils" :tone="mealSummary.planned > 0 && mealSummary.recorded === mealSummary.planned ? 'success' : 'default'"/><MetricCard class="animate-slide-in-up" label="当前目标" :value="store.isAthleteMode ? '基础准备' : '基础体能'" hint="查看目标说明" :icon="Target"/></div>
    <div class="grid"><BaseCard class="today animate-slide-in-up"><div class="card-head"><div><span class="eyebrow">TODAY'S SESSION</span><h3>今天的训练</h3></div><StatusBadge variant="info">待完成</StatusBadge></div><div class="session-row" v-for="s in sessionItems" :key="s.name"><div class="session-icon"><component :is="s.icon" :size="18"/></div><div><strong>{{s.name}}</strong><small>{{s.detail}}</small></div><span class="duration">{{s.duration}}</span></div><div class="card-actions"><BaseButton :icon="Play" @click="start('坐站训练')">开始训练</BaseButton><BaseButton variant="secondary" :icon="MoreHorizontal" @click="router.push('/plan')">查看详情</BaseButton></div></BaseCard><BaseCard class="meal-card animate-slide-in-up"><div class="card-head"><div><span class="eyebrow">MEAL LOG</span><h3>饮食记录</h3></div><StatusBadge :variant="mealBadgeVariant">{{ mealBadge }}</StatusBadge></div><div class="meal-progress"><div class="meal-count"><strong>{{ mealSummary.recorded }}</strong><span>/ {{ mealSummary.planned }}</span></div><div class="meal-body"><strong>{{ mealTitle }}</strong><p>{{ mealLine }}</p><div class="segs" role="img" :aria-label="segsAria"><span class="seg" v-for="s in mealSummary.slots" :key="s.id"><i :class="segState(s)"></i><b>{{ s.label }}</b></span></div><RouterLink to="/meals" class="meal-link">{{ mealSummary.recorded ? '补记或修改' : '去记录' }} <ArrowRight :size="14"/></RouterLink></div></div><div class="notice">没记录的餐次只显示"未记录"，不会被判断成"没有吃"。</div></BaseCard></div>
    <InsightCard class="why animate-slide-in-up" card-id="why-plan" eyebrow="WHY THIS PLAN" title="这份计划为什么适合你？"><template #icon><Sparkles :size="21" /></template><p>{{ store.isAthleteMode ? '依据：当前基础准备期、个人跑步周期与已锁定训练安排。只提出局部调整，不会自动改写周期计划。' : '依据：20 分钟可用时间、无器材、入门经验与无跳跃偏好。你可以随时调整条件。' }}</p></InsightCard>
  </div>
</template>
<script setup lang="ts">
import { computed } from 'vue'; import { useRouter } from 'vue-router'; import { useAppStore } from '@/stores/app'; import { Play, SlidersHorizontal, Activity, PlayCircle, GitCompare, TrendingUp, CheckCircle2, Clock3, Utensils, Target, MoreHorizontal, ArrowRight, Sparkles, Flame, PersonStanding, Wind } from 'lucide-vue-next'; import BaseCard from '@/components/common/BaseCard.vue'; import BaseButton from '@/components/common/BaseButton.vue'; import MetricCard from '@/components/common/MetricCard.vue'; import StatusBadge from '@/components/common/StatusBadge.vue'; import InsightCard from '@/components/common/InsightCard.vue'; import { eyebrowDate, greeting, displayName, toISODate } from '@/utils/time'; import { summarizeDay } from '@/services/mealRules'; import { buildWeeklyReport } from '@/services/weekRules';
const router=useRouter(); const store=useAppStore(); const now=new Date(); const eyebrow=eyebrowDate(now); const hello=greeting(now); const nickname=computed(()=>displayName(store.userProfile?.nickname));
const mealSummary=computed(()=>summarizeDay(store.meals,toISODate(now)));
const week=computed(()=>buildWeeklyReport(store.sessions,store.meals,now));
const weekValue=computed(()=>`${week.value.completedSessions} / ${week.value.plannedSessions}`);
const loadValue=computed(()=>week.value.totalLoad === null ? '未记录' : String(week.value.totalLoad));
const mealLabel='今日餐次记录';
const mealValue=computed(()=>`${mealSummary.value.recorded} / ${mealSummary.value.planned}`);
const mealHint=computed(()=>`类别覆盖 ${mealSummary.value.coverage.length}/8`);
const segState = (s: { meal?: { completeness: string } | null }) => !s.meal ? 'none' : s.meal.completeness === 'complete' ? 'complete' : 'partial';
const segsAria = computed(() => mealSummary.value.slots.map(s => `${s.label}：${s.meal ? (s.meal.completeness === 'complete' ? '已记录' : '部分记录') : '未记录'}`).join('；'));
const mealBadge=computed(()=>mealSummary.value.recorded===0?'未记录':mealSummary.value.recorded<mealSummary.value.planned?'部分记录':'已记录');
const mealBadgeVariant=computed<'neutral'|'warning'|'success'>(()=>mealSummary.value.recorded===0?'neutral':mealSummary.value.recorded<mealSummary.value.planned?'warning':'success');
const mealTitle=computed(()=>mealSummary.value.recorded?`今天已记录 ${mealSummary.value.recorded} 餐`:'今天还没有餐次记录');
const mealLine=computed(()=>{
  const s=mealSummary.value;
  const done=s.slots.filter(x=>x.meal).map(x=>x.label).join('、');
  const miss=s.slots.filter(x=>!x.meal).map(x=>x.label).join('、');
  if(!s.recorded)return '还没有记录。填一下今天吃了什么，结构分析才有输入。';
  return `已记录：${done}${miss?`；未记录：${miss}`:'；三餐都记上了'}。`;
}); const start=(exercise:string)=>router.push({path:'/execution',query:{exercise}}); const sessionItems=[{name:'动态热身',detail:'舒展 · 激活全身',duration:'4 min',icon:Wind},{name:'坐站训练',detail:'2 组 × 8 次',duration:'6 min',icon:PersonStanding},{name:'站姿弯举',detail:'2 组 × 10 次',duration:'6 min',icon:Flame},{name:'舒缓整理',detail:'呼吸 · 放松',duration:'4 min',icon:Activity}]
</script>
