n-bottom:22px}.card-head h3{font-size:22px;margin-top:7px}.session-row{display:flex;align-items:center;gap:12px;padding:13px 10px;margin:0 -10px;border-bottom:1px solid var(--color-divider);border-radius:12px;transition:background var(--motion-fast) var(--easing-ease-out),transform var(--motion-fast) var(--easing-ease-out)}.session-row:last-of-type{border-bottom:0}.session-row:hover{background:linear-gradient(90deg,var(--color-accent-soft),var(--color-neutral-soft));transform:translateX(3px)}.session-row>div:nth-child(2){flex:1}.session-icon{width:38px;height:38px;border-radius:12px;display:grid;place-items:center;color:var(--color-accent);background:linear-gradient(140deg,var(--color-accent-soft),var(--color-neutral-soft));box-shadow:inset 0 1px 0 #fff,0 0 0 1px rgba(15,118,110,.1);transition:transform var(--motion-base) var(--easing-spring)}.session-row:hover .session-icon{transform:scale(1.08) rotate(-6deg)}.session-row strong,.session-row small{display:block}.session-row small{color:var(--color-text-muted);font-size:12px;margin-top:2px}.duration{color:var(--color-text-secondary);font-size:13px}.card-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:21px}.meal-progress{display:flex;align-items:flex-start;gap:16px;margin:18px 0 20px}.meal-count{flex:none;display:flex;align-items:baseline;gap:3px;color:var(--color-ink)}.meal-count strong{font-family:var(--font-display);font-size:30px;letter-spacing:-.03em;font-variant-numeric:tabular-nums}.meal-count span{font-size:13px;color:var(--color-text-muted);font-variant-numeric:tabular-nums}.meal-body{flex:1;min-width:0}.meal-body>strong{font-size:14px;color:var(--color-ink)}
